import { createRoute, z } from '@hono/zod-openapi'

type ObjectType = { type: string }

const ObjectSchema: z.ZodType<ObjectType> = z
  .looseObject({ type: z.string() })
  .openapi({
    description:
      "Base type for most resource objects. It defines the common `type` element that identifies an object's type. It also identifies the element as Swagger's `discriminator`.",
    required: ['type'],
    discriminator: { propertyName: 'type' },
  })
  .openapi('Object')

const LinkSchema = z
  .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
  .openapi({
    title: 'Link',
    description: 'A link to a resource related to this object.',
    required: [],
  })
  .openapi('Link')

const AccountLinksSchema = z
  .looseObject({ avatar: LinkSchema.exactOptional() })
  .openapi({ title: 'Account Links', description: 'Links related to an Account.', required: [] })
  .openapi('AccountLinks')

type AccountType = z.infer<typeof ObjectSchema> & {
  links?: z.infer<typeof AccountLinksSchema>
  created_on?: string
  display_name?: string
  uuid?: string
}

const AccountSchema: z.ZodType<AccountType> = ObjectSchema.and(
  z
    .looseObject({
      links: AccountLinksSchema.exactOptional(),
      created_on: z.iso.datetime({ offset: true }).exactOptional(),
      display_name: z.string().exactOptional(),
      uuid: z.string().exactOptional(),
    })
    .openapi({ title: 'Account', description: 'An account object.', required: [] }),
).openapi('Account')

const TeamLinksSchema = AccountLinksSchema.and(
  z
    .looseObject({
      self: LinkSchema.exactOptional(),
      html: LinkSchema.exactOptional(),
      members: LinkSchema.exactOptional(),
      projects: LinkSchema.exactOptional(),
      repositories: LinkSchema.exactOptional(),
    })
    .openapi({ title: 'Team Links', description: 'Links related to a Team.', required: [] }),
).openapi('TeamLinks')

const TeamSchema = AccountSchema.and(
  z
    .looseObject({ links: TeamLinksSchema.exactOptional() })
    .openapi({ title: 'Team', description: 'A team object.', required: [] }),
).openapi('Team')

type ProjectType = z.infer<typeof ObjectSchema> & {
  links?: { html?: { href?: string; name?: string }; avatar?: { href?: string; name?: string } }
  uuid?: string
  key?: string
  owner?: z.infer<typeof TeamSchema>
  name?: string
  description?: string
  is_private?: boolean
  created_on?: string
  updated_on?: string
  has_publicly_visible_repos?: boolean
}

const ProjectSchema: z.ZodType<ProjectType> = ObjectSchema.and(
  z
    .looseObject({
      links: z
        .strictObject({
          html: z
            .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
            .exactOptional()
            .openapi({
              title: 'Link',
              description: 'A link to a resource related to this object.',
              required: [],
            }),
          avatar: z
            .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
            .exactOptional()
            .openapi({
              title: 'Link',
              description: 'A link to a resource related to this object.',
              required: [],
            }),
        })
        .exactOptional()
        .openapi({ required: [] }),
      uuid: z.string().exactOptional().openapi({ description: "The project's immutable id." }),
      key: z.string().exactOptional().openapi({ description: "The project's key." }),
      owner: TeamSchema.exactOptional(),
      name: z.string().exactOptional().openapi({ description: 'The name of the project.' }),
      description: z.string().exactOptional(),
      is_private: z
        .boolean()
        .exactOptional()
        .openapi({
          description:
            '\nIndicates whether the project is publicly accessible, or whether it is\nprivate to the team and consequently only visible to team members.\nNote that private projects cannot contain public repositories.',
        }),
      created_on: z.iso.datetime({ offset: true }).exactOptional(),
      updated_on: z.iso.datetime({ offset: true }).exactOptional(),
      has_publicly_visible_repos: z
        .boolean()
        .exactOptional()
        .openapi({
          description:
            '\nIndicates whether the project contains publicly visible repositories.\nNote that private projects cannot contain public repositories.',
        }),
    })
    .openapi({
      title: 'Project',
      description:
        'A Bitbucket project.\n            Projects are used by teams to organize repositories.',
      required: [],
    }),
).openapi('Project')

const BranchSchema: z.ZodType<BranchType> = z
  .lazy(() =>
    RefSchema.and(
      z
        .looseObject({
          merge_strategies: z
            .array(
              z.enum([
                'merge_commit',
                'squash',
                'fast_forward',
                'squash_fast_forward',
                'rebase_fast_forward',
                'rebase_merge',
              ]),
            )
            .exactOptional()
            .openapi({
              description: 'Available merge strategies for pull requests targeting this branch.',
            }),
          default_merge_strategy: z
            .string()
            .exactOptional()
            .openapi({
              description: 'The default merge strategy for pull requests targeting this branch.',
            }),
        })
        .openapi({
          title: 'Branch',
          description: 'A branch object, representing a branch in a repository.',
          required: [],
        }),
    ),
  )
  .openapi('Branch')

type RepositoryType = z.infer<typeof ObjectSchema> & {
  links?: {
    self?: { href?: string; name?: string }
    html?: { href?: string; name?: string }
    avatar?: { href?: string; name?: string }
    pullrequests?: { href?: string; name?: string }
    commits?: { href?: string; name?: string }
    forks?: { href?: string; name?: string }
    watchers?: { href?: string; name?: string }
    downloads?: { href?: string; name?: string }
    clone?: { href?: string; name?: string }[]
    hooks?: { href?: string; name?: string }
  }
  uuid?: string
  full_name?: string
  is_private?: boolean
  parent?: RepositoryType
  scm?: 'git'
  owner?: z.infer<typeof AccountSchema>
  name?: string
  description?: string
  created_on?: string
  updated_on?: string
  size?: number
  language?: string
  has_issues?: boolean
  has_wiki?: boolean
  fork_policy?: 'allow_forks' | 'no_public_forks' | 'no_forks'
  project?: z.infer<typeof ProjectSchema>
  mainbranch?: z.infer<typeof BranchSchema>
}

type CommentType = z.infer<typeof ObjectSchema> & {
  id?: bigint
  created_on?: string
  updated_on?: string
  content?: { raw?: string; markup?: 'markdown' | 'creole' | 'plaintext'; html?: string }
  user?: z.infer<typeof AccountSchema>
  deleted?: boolean
  parent?: CommentType
  inline?: { from?: number; to?: number; start_from?: number; start_to?: number; path: string }
  links?: {
    self?: { href?: string; name?: string }
    html?: { href?: string; name?: string }
    code?: { href?: string; name?: string }
  }
}

type ParticipantType = z.infer<typeof ObjectSchema> & {
  user?: z.infer<typeof AccountSchema>
  role?: 'PARTICIPANT' | 'REVIEWER'
  approved?: boolean
  state?: 'approved' | 'changes_requested' | null
  participated_on?: string
}

const AuthorSchema = ObjectSchema.and(
  z
    .looseObject({
      raw: z
        .string()
        .exactOptional()
        .openapi({
          description:
            'The raw author value from the repository. This may be the only value available if the author does not match a user in Bitbucket.',
        }),
      user: AccountSchema.exactOptional(),
    })
    .openapi({
      title: 'Author',
      description: 'The author of a change in a repository',
      required: [],
    }),
).openapi('Author')

const CommitterSchema = ObjectSchema.and(
  z
    .looseObject({
      raw: z
        .string()
        .exactOptional()
        .openapi({
          description:
            'The raw committer value from the repository. This may be the only value available if the committer does not match a user in Bitbucket.',
        }),
      user: AccountSchema.exactOptional(),
    })
    .openapi({
      title: 'Committer',
      description: 'The committer of a change in a repository',
      required: [],
    }),
).openapi('Committer')

type BaseCommitType = z.infer<typeof ObjectSchema> & {
  hash?: string
  date?: string
  author?: z.infer<typeof AuthorSchema>
  committer?: z.infer<typeof CommitterSchema>
  message?: string
  summary?: { raw?: string; markup?: 'markdown' | 'creole' | 'plaintext'; html?: string }
  parents?: BaseCommitType[]
}

const CommitSchema: z.ZodType<CommitType> = z
  .lazy(() =>
    BaseCommitSchema.and(
      z
        .looseObject({
          repository: RepositorySchema.exactOptional(),
          participants: z.array(ParticipantSchema).min(0).exactOptional(),
        })
        .openapi({ title: 'Commit', description: 'A repository commit object.', required: [] }),
    ),
  )
  .openapi('Commit')

type RefType = {
  type: string
  links?: {
    self?: { href?: string; name?: string }
    commits?: { href?: string; name?: string }
    html?: { href?: string; name?: string }
  }
  name?: string
  target?: z.infer<typeof CommitSchema>
}

type GPGAccountKeyType = z.infer<typeof ObjectSchema> & {
  owner?: z.infer<typeof AccountSchema>
  key?: string
  key_id?: string
  fingerprint?: string
  parent_fingerprint?: string
  name?: string
  expires_on?: string
  created_on?: string
  added_on?: string
  last_used?: string
  subkeys?: GPGAccountKeyType[]
  links?: { self?: { href?: string; name?: string } }
}

const RefSchema: z.ZodType<RefType> = z
  .lazy(() =>
    z
      .looseObject({
        type: z.string(),
        links: z
          .strictObject({
            self: z
              .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
              .exactOptional()
              .openapi({
                title: 'Link',
                description: 'A link to a resource related to this object.',
                required: [],
              }),
            commits: z
              .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
              .exactOptional()
              .openapi({
                title: 'Link',
                description: 'A link to a resource related to this object.',
                required: [],
              }),
            html: z
              .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
              .exactOptional()
              .openapi({
                title: 'Link',
                description: 'A link to a resource related to this object.',
                required: [],
              }),
          })
          .exactOptional()
          .openapi({ required: [] }),
        name: z.string().exactOptional().openapi({ description: 'The name of the ref.' }),
        target: CommitSchema.exactOptional(),
      })
      .openapi({
        title: 'Ref',
        description: 'A ref object, representing a branch or tag in a repository.',
        required: ['type'],
      }),
  )
  .openapi('Ref')

type BranchType = z.infer<typeof RefSchema> & {
  merge_strategies?: (
    | 'merge_commit'
    | 'squash'
    | 'fast_forward'
    | 'squash_fast_forward'
    | 'rebase_fast_forward'
    | 'rebase_merge'
  )[]
  default_merge_strategy?: string
}

const BaseCommitSchema: z.ZodType<BaseCommitType> = z
  .lazy(() =>
    ObjectSchema.and(
      z
        .looseObject({
          hash: z
            .string()
            .regex(/[0-9a-f]{7,}?/)
            .exactOptional(),
          date: z.iso.datetime({ offset: true }).exactOptional(),
          author: AuthorSchema.exactOptional(),
          committer: CommitterSchema.exactOptional(),
          message: z.string().exactOptional(),
          summary: z
            .strictObject({
              raw: z
                .string()
                .exactOptional()
                .openapi({ description: 'The text as it was typed by a user.' }),
              markup: z
                .enum(['markdown', 'creole', 'plaintext'])
                .exactOptional()
                .openapi({
                  description:
                    'The type of markup language the raw content is to be interpreted in.',
                }),
              html: z
                .string()
                .exactOptional()
                .openapi({ description: "The user's content rendered as HTML." }),
            })
            .exactOptional()
            .openapi({ required: [] }),
          parents: z.array(BaseCommitSchema).min(0).exactOptional(),
        })
        .openapi({
          title: 'Base Commit',
          description: 'The common base type for both repository and snippet commits.',
          required: [],
        }),
    ),
  )
  .openapi('BaseCommit')

const RepositorySchema: z.ZodType<RepositoryType> = z
  .lazy(() =>
    ObjectSchema.and(
      z
        .looseObject({
          links: z
            .strictObject({
              self: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
              html: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
              avatar: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
              pullrequests: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
              commits: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
              forks: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
              watchers: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
              downloads: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
              clone: z
                .array(
                  z
                    .strictObject({
                      href: z.url().exactOptional(),
                      name: z.string().exactOptional(),
                    })
                    .openapi({
                      title: 'Link',
                      description: 'A link to a resource related to this object.',
                      required: [],
                    }),
                )
                .exactOptional(),
              hooks: z
                .strictObject({ href: z.url().exactOptional(), name: z.string().exactOptional() })
                .exactOptional()
                .openapi({
                  title: 'Link',
                  description: 'A link to a resource related to this object.',
                  required: [],
                }),
            })
            .exactOptional()
            .openapi({ required: [] }),
          uuid: z
            .string()
            .exactOptional()
            .openapi({
              description:
                "The repository's immutable id. This can be used as a substitute for the slug segment in URLs. Doing this guarantees your URLs will survive renaming of the repository by its owner, or even transfer of the repository to a different user.",
            }),
          full_name: z
            .string()
            .exactOptional()
            .openapi({
              description:
                'The concatenation of the repository owner\'s username and the slugified name, e.g. "evzijst/interruptingcow". This is the same string used in Bitbucket URLs.',
            }),
          is_private: z.boolean().exactOptional(),
          parent: RepositorySchema.exactOptional(),
          scm: z.literal('git').exactOptional(),
          owner: AccountSchema.exactOptional(),
          name: z.string().exactOptional(),
          description: z.string().exactOptional(),
          created_on: z.iso.datetime({ offset: true }).exactOptional(),
          updated_on: z.iso.datetime({ offset: true }).exactOptional(),
          size: z.int().exactOptional(),
          language: z.string().exactOptional(),
          has_issues: z
            .boolean()
            .exactOptional()
            .openapi({
              description:
                '\nThe issue tracker for this repository is enabled. Issue Tracker\nfeatures are not supported for repositories in workspaces\nadministered through admin.atlassian.com.\n',
            }),
          has_wiki: z
            .boolean()
            .exactOptional()
            .openapi({
              description:
                '\nThe wiki for this repository is enabled. Wiki\nfeatures are not supported for repositories in workspaces\nadministered through admin.atlassian.com.\n',
            }),
          fork_policy: z
            .enum(['allow_forks', 'no_public_forks', 'no_forks'])
            .exactOptional()
            .openapi({
              description:
                '\nControls the rules for forking this repository.\n\n* **allow_forks**: unrestricted forking\n* **no_public_forks**: restrict forking to private forks (forks cannot\n  be made public later)\n* **no_forks**: deny all forking\n',
            }),
          project: ProjectSchema.exactOptional(),
          mainbranch: BranchSchema.exactOptional(),
        })
        .openapi({ title: 'Repository', description: 'A Bitbucket repository.', required: [] }),
    ),
  )
  .openapi('Repository')

const ParticipantSchema: z.ZodType<ParticipantType> = ObjectSchema.and(
  z
    .looseObject({
      user: AccountSchema.exactOptional(),
      role: z.enum(['PARTICIPANT', 'REVIEWER']).exactOptional(),
      approved: z.boolean().exactOptional(),
      state: z
        .union([z.literal('approved'), z.literal('changes_requested'), z.literal(null)])
        .exactOptional(),
      participated_on: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          description:
            "The ISO8601 timestamp of the participant's action. For approvers, this is the time of their approval. For commenters and pull request reviewers who are not approvers, this is the time they last commented, or null if they have not commented.",
        }),
    })
    .openapi({
      title: 'Participant',
      description: "Object describing a user's role on resources like commits or pull requests.",
      required: [],
    }),
).openapi('Participant')

type CommitType = z.infer<typeof BaseCommitSchema> & {
  repository?: z.infer<typeof RepositorySchema>
  participants?: z.infer<typeof ParticipantSchema>[]
}

const WebhooksSubscriptionLinkSchema = z
  .object({ href: z.url().exactOptional() })
  .openapi({ title: 'Link', required: [] })
  .openapi('WebhooksSubscriptionLink')

const WebhooksSubscriptionLinksSchema = z
  .looseObject({ self: WebhooksSubscriptionLinkSchema.exactOptional() })
  .openapi({
    title: 'Webhooks Links',
    description: 'A link to a resource related to this object.',
    required: [],
  })
  .openapi('WebhooksSubscriptionLinks')

const WebhookSubscriptionSchema = ObjectSchema.and(
  z
    .looseObject({
      uuid: z
        .string()
        .exactOptional()
        .openapi({ description: "The webhook's id.", readOnly: true }),
      url: z.url().exactOptional().openapi({ description: 'The URL events get delivered to.' }),
      description: z
        .string()
        .exactOptional()
        .openapi({ description: 'A user-defined description of the webhook.' }),
      subject_type: z
        .enum(['repository', 'workspace'])
        .exactOptional()
        .openapi({
          description:
            'The type of entity. Set to either `repository` or `workspace` based on where the subscription is defined.',
          readOnly: true,
        }),
      subject: ObjectSchema.exactOptional(),
      active: z
        .boolean()
        .exactOptional()
        .openapi({ description: 'Whether or not the webhook subscription is enabled.' }),
      created_at: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          description: 'The timestamp when the webhook subscription was created.',
          readOnly: true,
        }),
      events: z
        .array(
          z.enum([
            'issue:comment_created',
            'issue:created',
            'issue:updated',
            'pipeline:span_created',
            'project:updated',
            'pullrequest:approved',
            'pullrequest:changes_request_created',
            'pullrequest:changes_request_removed',
            'pullrequest:comment_created',
            'pullrequest:comment_deleted',
            'pullrequest:comment_reopened',
            'pullrequest:comment_resolved',
            'pullrequest:comment_updated',
            'pullrequest:created',
            'pullrequest:fulfilled',
            'pullrequest:push',
            'pullrequest:rejected',
            'pullrequest:unapproved',
            'pullrequest:updated',
            'repo:commit_comment_created',
            'repo:commit_status_created',
            'repo:commit_status_updated',
            'repo:created',
            'repo:deleted',
            'repo:fork',
            'repo:imported',
            'repo:push',
            'repo:transfer',
            'repo:updated',
          ]),
        )
        .min(1)
        .superRefine((items, ctx) => {
          const seen = new Map()
          for (const [i, val] of items.entries()) {
            const key = JSON.stringify(val)
            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
            else seen.set(key, i)
          }
        })
        .exactOptional()
        .openapi({ description: 'The events this webhook is subscribed to.' }),
      secret_set: z
        .boolean()
        .exactOptional()
        .openapi({
          description:
            "Indicates whether or not the hook has an associated secret. It is not possible to see the hook's secret. This field is ignored during updates.",
          readOnly: true,
        }),
      secret: z
        .string()
        .min(0)
        .max(128)
        .exactOptional()
        .openapi({
          description:
            'The secret to associate with the hook. The secret is never returned via the API. As such, this field is only used during updates. The secret can be set to `null`` or `""`` to remove the secret (or create a hook with no secret). Leaving out the secret field during updates will leave the secret unchanged. Leaving out the secret during creation will create a hook with no secret.',
        }),
      links: WebhooksSubscriptionLinksSchema.exactOptional(),
    })
    .openapi({
      title: 'Webhook Subscription',
      description: 'A Webhook subscription.',
      required: [],
    }),
).openapi('WebhookSubscription')

const PaginatedWebhookSubscriptionsSchema = z
  .strictObject({
    values: z
      .array(WebhookSubscriptionSchema)
      .min(0)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional(),
    pagelen: z
      .int()
      .min(1)
      .max(100)
      .exactOptional()
      .openapi({
        description:
          'Current number of objects on the existing page. The default value is 10 with 100 being the maximum allowed value. Individual APIs may enforce different values.',
      }),
    next: z
      .url()
      .exactOptional()
      .openapi({
        description:
          'Link to the next page if it exists. The last page of a collection does not have this value. Use this link to navigate the result set and refrain from constructing your own URLs.',
      }),
  })
  .openapi({
    title: 'Paginated Webhook Subscriptions',
    description: 'A paginated list of webhook subscriptions',
    required: [],
  })
  .openapi('PaginatedWebhookSubscriptions')

