const CustomMergeCheckSchema = PullrequestMergeabilityCheckSchema.and(
  z
    .looseObject({
      type: z.enum(['custom_pre_merge_check', 'custom_on_merge_check']),
      check: z
        .looseObject({})
        .openapi({
          description:
            "Identifies which custom check this is, as `{'type': 'custom_merge_check_definition', 'id': '...', 'name': '...'}`, where `id` is the ARI of the custom check extension.",
        }),
      uuid: z
        .string()
        .exactOptional()
        .openapi({
          description:
            'Present when a persisted result exists: the persisted custom check result UUID. Omitted for on-merge checks known but not yet triggered.',
        }),
      message: z
        .string()
        .exactOptional()
        .openapi({
          description: 'Present when the custom check provides one; omitted when absent.',
        }),
    })
    .openapi({
      title: 'Custom Merge Check',
      description:
        "One per configured custom merge check, if the workspace has activated custom merge checks - omitted entirely otherwise. `type` is `custom_pre_merge_check` for a persisted result of a check that already ran before the merge action, or `custom_on_merge_check` for a check that runs as part of the merge action itself (which may be known but not yet triggered). This endpoint never triggers or retries a custom check, it only reports results. If custom checks are activated but their results cannot currently be retrieved, the whole request fails with `500` instead of omitting them or fabricating a placeholder - merging already requires custom checks to be retrievable, so this endpoint can't accurately report mergeability either.",
      required: ['type', 'check'],
    }),
).openapi('CustomMergeCheck')

