export const getAddonAddonKeyClientKeyRoute = createRoute({
  method: 'get',
  path: '/addon/{addon_key}/client-key',
  tags: ['Addon'],
  summary: 'Get the client key of a Connect addon',
  description:
    'Get the client key of the Connect addon associated with a Forge app install via forgeAppId linkage.\n\nThis endpoint is part of the Connect -> Forge migration tooling. It is intended to be used by a Forge app\nusing `asApp().requestBitbucket()` only.\nPrerequisite: app developer needs to register the linkage between their Connect and Forge app by setting\n`forgeAppId` in the Connect addon descriptor to `app.id` from Forge app manifest, then update the installations.\nIf the request came from an installation of a registered Forge app, the client key of the linked Connect addon\ninstalled in the same workspace will be returned.\n\n```\napi.asApp().requestBitbucket(route`/2.0/addon/{addon-key}/client-key`)\n```',
  request: {
    params: z.object({
      addon_key: z
        .string()
        .openapi({
          param: {
            name: 'addon_key',
            in: 'path',
            description: 'The Connect addon key as defined in an application descriptor.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'The client key of the Connect addon linked to the Forge app installation where the request was made',
    },
    401: {
      description: 'Invalid authentication.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    403: {
      description: 'Improper authorization.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    404: {
      description: 'The Connect addon or the Forge app does not exist.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: [] }, { basic: [] }, { api_key: [] }],
})

