export const postRepositoriesWorkspaceRepoSlugCommitCommitCommentsRoute = createRoute({
  method: 'post',
  path: '/repositories/{workspace}/{repo_slug}/commit/{commit}/comments',
  tags: ['Commits'],
  summary: 'Create comment for a commit',
  description:
    'Creates new comment on the specified commit.\n\nTo post a reply to an existing comment, include the `parent.id` field:\n\n```\n$ curl https://api.bitbucket.org/2.0/repositories/atlassian/prlinks/commit/db9ba1e031d07a02603eae0e559a7adc010257fc/comments/ \\\n  -X POST -u evzijst \\\n  -H \'Content-Type: application/json\' \\\n  -d \'{"content": {"raw": "One more thing!"},\n       "parent": {"id": 5728901}}\'\n```',
  request: {
    params: z.object({
      commit: z
        .string()
        .openapi({
          param: {
            name: 'commit',
            in: 'path',
            description: "The commit's SHA1.",
            required: true,
            schema: { type: 'string' },
          },
        }),
      repo_slug: z
        .string()
        .openapi({
          param: {
            name: 'repo_slug',
            in: 'path',
            description:
              'This can either be the repository slug or the UUID of the repository,\nsurrounded by curly-braces, for example: `{repository UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      description: 'The specified comment.',
      content: { 'application/json': { schema: CommitCommentSchema } },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'The newly created comment.',
      headers: z.object({
        Location: {
          description: 'The location of the newly created comment.',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'The location of the newly created comment.',
              param: { required: false },
            }),
        },
      }),
    },
    400: {
      description:
        'If the comment was detected as spam, or if the parent comment is not attached to the same node as the new comment',
    },
    404: { description: 'If a parent ID was passed in that cannot be found' },
  },
  security: [{ oauth2: ['repository'] }, { basic: [] }, { api_key: [] }],
})

export const getRepositoriesWorkspaceRepoSlugCommitCommitCommentsCommentIdRoute = createRoute({
  method: 'get',
  path: '/repositories/{workspace}/{repo_slug}/commit/{commit}/comments/{comment_id}',
  tags: ['Commits'],
  summary: 'Get a commit comment',
  description: 'Returns the specified commit comment.',
  request: {
    params: z.object({
      comment_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'comment_id',
            in: 'path',
            description: 'The id of the comment.',
            required: true,
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      commit: z
        .string()
        .openapi({
          param: {
            name: 'commit',
            in: 'path',
            description: "The commit's SHA1.",
            required: true,
            schema: { type: 'string' },
          },
        }),
      repo_slug: z
        .string()
        .openapi({
          param: {
            name: 'repo_slug',
            in: 'path',
            description:
              'This can either be the repository slug or the UUID of the repository,\nsurrounded by curly-braces, for example: `{repository UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The commit comment.',
      content: { 'application/json': { schema: CommitCommentSchema } },
    },
  },
  security: [{ oauth2: ['repository'] }, { basic: [] }, { api_key: [] }],
})

