export const getRepositoriesWorkspaceRepoSlugCommitCommitPullrequestsRoute = createRoute({
  method: 'get',
  path: '/repositories/{workspace}/{repo_slug}/commit/{commit}/pullrequests',
  tags: ['Pullrequests'],
  summary: 'List pull requests that contain a commit',
  description:
    "Returns a paginated list of all pull requests as part of which this commit was reviewed. Pull Request Commit Links app must be installed first before using this API; installation automatically occurs when 'Go to pull request' is clicked from the web interface for a commit's details.",
  operationId: 'getPullrequestsForCommit',
  request: {
    params: z.object({
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description:
              'This can either be the workspace ID (slug) or the workspace UUID surrounded by curly-braces',
            required: true,
            schema: { type: 'string' },
          },
        }),
      repo_slug: z
        .string()
        .openapi({
          param: {
            name: 'repo_slug',
            in: 'path',
            description: 'The repository; either the UUID in curly braces, or the slug',
            required: true,
            schema: { type: 'string' },
          },
        }),
      commit: z
        .string()
        .openapi({
          param: {
            name: 'commit',
            in: 'path',
            description: 'The SHA1 of the commit',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'Which page to retrieve',
            required: false,
            schema: { type: 'integer', format: 'int32', default: 1 },
          },
        }),
      pagelen: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(30)
        .exactOptional()
        .openapi({
          param: {
            name: 'pagelen',
            in: 'query',
            description: 'How many pull requests to retrieve per page',
            required: false,
            schema: { type: 'integer', format: 'int32', default: 30 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The paginated list of pull requests.',
      content: { 'application/json': { schema: PaginatedPullrequestsSchema } },
    },
    202: {
      description: "The repository's pull requests are still being indexed.",
      content: { 'application/json': { schema: PaginatedPullrequestsSchema } },
    },
    404: {
      description:
        'Either the repository does not exist, or pull request commit links have not yet been indexed.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['pullrequest'] }, { basic: [] }, { api_key: [] }],
})

