export const getRepositoriesWorkspaceRepoSlugDiffSpecRoute = createRoute({
  method: 'get',
  path: '/repositories/{workspace}/{repo_slug}/diff/{spec}',
  tags: ['Commits'],
  summary: 'Compare two commits',
  description:
    "Produces a raw git-style diff.\n\n#### Single commit spec\n\nIf the `spec` argument to this API is a single commit, the diff is\nproduced against the first parent of the specified commit.\n\n#### Two commit spec\n\nTwo commits separated by `..` may be provided as the `spec`, e.g.,\n`3a8b42..9ff173`. When two commits are provided and the `topic` query\nparameter is true, this API produces a 2-way three dot diff.\nThis is the diff between source commit and the merge base of the source\ncommit and the destination commit. When the `topic` query param is false,\na simple git-style diff is produced.\n\nThe two commits are interpreted as follows:\n\n* First commit: the commit containing the changes we wish to preview\n* Second commit: the commit representing the state to which we want to\n  compare the first commit\n* **Note**: This is the opposite of the order used in `git diff`.\n\n#### Comparison to patches\n\nWhile similar to patches, diffs:\n\n* Don't have a commit header (username, commit message, etc)\n* Support the optional `path=foo/bar.py` query param to filter\n  the diff to just that one file diff\n\n#### Response\n\nThe raw diff is returned as-is, in whatever encoding the files in the\nrepository use. It is not decoded into unicode. As such, the\ncontent-type is `text/plain`.",
  request: {
    params: z.object({
      repo_slug: z
        .string()
        .openapi({
          param: {
            name: 'repo_slug',
            in: 'path',
            description:
              'This can either be the repository slug or the UUID of the repository,\nsurrounded by curly-braces, for example: `{repository UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
      spec: z
        .string()
        .openapi({
          param: {
            name: 'spec',
            in: 'path',
            description:
              'A commit SHA (e.g. `3a8b42`) or a commit range using double dot\nnotation (e.g. `3a8b42..9ff173`).\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      context: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'context',
            in: 'query',
            description: 'Generate diffs with <n> lines of context instead of the usual three.',
            required: false,
            schema: { type: 'integer' },
          },
        }),
      path: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'path',
            in: 'query',
            description:
              'Limit the diff to a particular file (this parameter\ncan be repeated for multiple paths).',
            required: false,
            schema: { type: 'string' },
          },
        }),
      ignore_whitespace: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'ignore_whitespace',
            in: 'query',
            description: 'Generate diffs that ignore whitespace.',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      binary: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'binary',
            in: 'query',
            description: 'Generate diffs that include binary files, true if omitted.',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      renames: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'renames',
            in: 'query',
            description: 'Whether to perform rename detection, true if omitted.',
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      merge: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'merge',
            in: 'query',
            description:
              "This parameter is deprecated. The 'topic' parameter should be used\ninstead. The 'merge' and 'topic' parameters cannot be both used at\nthe same time.\n\nIf true, the source commit is merged into the\ndestination commit, and then a diff from the\ndestination to the merge result is returned. If false,\na simple 'two dot' diff between the source and\ndestination is returned. True if omitted.",
            required: false,
            schema: { type: 'boolean' },
          },
        }),
      topic: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'topic',
            in: 'query',
            description:
              "If true, returns 2-way 'three-dot' diff.\nThis is a diff between the source commit and the merge base\nof the source commit and the destination commit.\nIf false, a simple 'two dot' diff between the source and\ndestination is returned.\n\nIf omitted, defaults to true, ie. a 2 way 'three-dot'\ndiff is returned.\n",
            required: false,
            schema: { type: 'boolean' },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'The raw diff' },
    555: {
      description:
        'If the diff was too large and timed out.\n\nSince this endpoint does not employ any form of pagination, but\ninstead returns the diff as a single document, it can run into\ntrouble on very large diffs. If Bitbucket times out in cases\nlike these, a 555 status code is returned.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['repository'] }, { basic: [] }, { api_key: [] }],
})

