export const getRepositoriesWorkspaceRepoSlugFilehistoryCommitPathRoute = createRoute({
  method: 'get',
  path: '/repositories/{workspace}/{repo_slug}/filehistory/{commit}/{path}',
  tags: ['Source', 'Repositories'],
  summary: 'List commits that modified a file',
  description:
    "Returns a paginated list of commits that modified the specified file.\n\nCommits are returned in reverse chronological order. This is roughly\nequivalent to the following commands:\n\n    $ git log --follow --date-order <sha> <path>\n\nBy default, Bitbucket will follow renames and the path name in the\nreturned entries reflects that. This can be turned off using the\n`?renames=false` query parameter.\n\nResults are returned in descending chronological order by default, and\nlike most endpoints you can\n[filter and sort](/cloud/bitbucket/rest/intro/#filtering) the response to\nonly provide exactly the data you want.\n\nThe example response returns commits made before 2011-05-18 against a file\nnamed `README.rst`. The results are filtered to only return the path and\ndate. This request can be made using:\n\n```\n$ curl 'https://api.bitbucket.org/2.0/repositories/evzijst/dogslow/filehistory/master/README.rst'\\\n  '?fields=values.next,values.path,values.commit.date&q=commit.date<=2011-05-18'\n```\n\nIn the response you can see that the file was renamed to `README.rst`\nby the commit made on 2011-05-16, and was previously named `README.txt`.",
  request: {
    params: z.object({
      commit: z
        .string()
        .openapi({
          param: {
            name: 'commit',
            in: 'path',
            description: "The commit's SHA1.",
            required: true,
            schema: { type: 'string' },
          },
        }),
      path: z
        .string()
        .openapi({
          param: {
            name: 'path',
            in: 'path',
            description: 'Path to the file.',
            required: true,
            schema: { type: 'string' },
          },
        }),
      repo_slug: z
        .string()
        .openapi({
          param: {
            name: 'repo_slug',
            in: 'path',
            description:
              'This can either be the repository slug or the UUID of the repository,\nsurrounded by curly-braces, for example: `{repository UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      renames: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'renames',
            in: 'query',
            description:
              '\nWhen `true`, Bitbucket will follow the history of the file across\nrenames (this is the default behavior). This can be turned off by\nspecifying `false`.',
            required: false,
            schema: { type: 'string' },
          },
        }),
      q: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'q',
            in: 'query',
            description:
              '\nQuery string to narrow down the response as per\n[filtering and sorting](/cloud/bitbucket/rest/intro/#filtering).',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            in: 'query',
            description:
              '\nName of a response property sort the result by as per\n[filtering and sorting](/cloud/bitbucket/rest/intro/#sorting-query-results).\n',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A paginated list of commits that modified the specified file',
      content: {
        'application/json': {
          schema: PaginatedFilesSchema,
          examples: {
            response: {
              value: {
                values: [
                  { commit: { date: '2011-05-17T07:32:09+00:00' }, path: 'README.rst' },
                  { commit: { date: '2011-05-16T06:33:28+00:00' }, path: 'README.txt' },
                  { commit: { date: '2011-05-16T06:15:39+00:00' }, path: 'README.txt' },
                ],
              },
            },
          },
        },
      },
    },
    404: {
      description: 'If the repository does not exist.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['repository'] }, { basic: [] }, { api_key: [] }],
})

