export const getRepositoriesWorkspaceRepoSlugMergeQueuesRoute = createRoute({
  method: 'get',
  path: '/repositories/{workspace}/{repo_slug}/merge-queues',
  tags: ['Merge queues'],
  summary: 'List merge queues',
  description: 'Lists merge queues configured for a repository. Optionally filter by branch.',
  operationId: 'listMergeQueues',
  request: {
    params: z.object({
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            description: 'The workspace containing the repository.',
            required: true,
            in: 'path',
            schema: { type: 'string' },
          },
        }),
      repo_slug: z
        .string()
        .openapi({
          param: {
            name: 'repo_slug',
            description: 'The repository slug.',
            required: true,
            in: 'path',
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      target_branch: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'target_branch',
            description: 'Optional target branch name to filter merge queues.',
            required: false,
            in: 'query',
            schema: { type: 'string' },
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            description: 'The page number of elements to retrieve.',
            required: false,
            in: 'query',
            schema: { type: 'integer', format: 'int32', minimum: 1, default: 1 },
          },
        }),
      pagelen: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(100),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'pagelen',
            description: 'The maximum number of results to return.',
            required: false,
            in: 'query',
            schema: { type: 'integer', format: 'int32', minimum: 1, maximum: 100, default: 10 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Merge queues retrieved successfully.',
      content: { 'application/json': { schema: PaginatedMergeQueuesSchema } },
    },
    401: {
      description: 'Authentication is required.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    403: {
      description: 'The caller does not have read access to the repository.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    404: {
      description: 'The repository does not exist.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['repository'] }, { basic: [] }, { api_key: [] }],
})

