export const getRepositoriesWorkspaceRepoSlugPatchSpecRoute = createRoute({
  method: 'get',
  path: '/repositories/{workspace}/{repo_slug}/patch/{spec}',
  tags: ['Commits'],
  summary: 'Get a patch for two commits',
  description:
    'Produces a raw patch for a single commit (diffed against its first\nparent), or a patch-series for a revspec of 2 commits (e.g.\n`3a8b42..9ff173` where the first commit represents the source and the\nsecond commit the destination).\n\nIn case of the latter (diffing a revspec), a patch series is returned\nfor the commits on the source branch (`3a8b42` and its ancestors in\nour example).\n\nWhile similar to diffs, patches:\n\n* Have a commit header (username, commit message, etc)\n* Do not support the `path=foo/bar.py` query parameter\n\nThe raw patch is returned as-is, in whatever encoding the files in the\nrepository use. It is not decoded into unicode. As such, the\ncontent-type is `text/plain`.',
  request: {
    params: z.object({
      repo_slug: z
        .string()
        .openapi({
          param: {
            name: 'repo_slug',
            in: 'path',
            description:
              'This can either be the repository slug or the UUID of the repository,\nsurrounded by curly-braces, for example: `{repository UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
      spec: z
        .string()
        .openapi({
          param: {
            name: 'spec',
            in: 'path',
            description:
              'A commit SHA (e.g. `3a8b42`) or a commit range using double dot\nnotation (e.g. `3a8b42..9ff173`).\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'The raw patches' },
    555: {
      description:
        'If the diff was too large and timed out.\n\nSince this endpoint does not employ any form of pagination, but\ninstead returns the diff as a single document, it can run into\ntrouble on very large diffs. If Bitbucket times out in cases\nlike these, a 555 status code is returned.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['repository'] }, { basic: [] }, { api_key: [] }],
})

