export const getWorkspacesWorkspaceMembersRoute = createRoute({
  method: 'get',
  path: '/workspaces/{workspace}/members',
  tags: ['Workspaces'],
  summary: 'List users in a workspace',
  description:
    'Returns all members of the requested workspace.\n\nThis endpoint additionally supports [filtering](/cloud/bitbucket/rest/intro/#filtering) by\nemail address, if called by a workspace administrator, integration or workspace access\ntoken. This is done by adding the following query string parameter:\n\n* `q=user.email IN ("user1@org.com","user2@org.com")`\n\nWhen filtering by email, you can query up to 90 addresses at a time.\nNote that the query parameter values need to be URL escaped, so the final query string\nshould be:\n\n* `q=user.email%20IN%20(%22user1@org.com%22,%22user2@org.com%22)`\n\nEmail addresses that you filter by (and only these email addresses) can be included in the\nresponse using the `fields` query parameter:\n\n* `&fields=+values.user.email` - add the `email` field to the default `user` response object\n* `&fields=values.user.email,values.user.account_id` - only return user email addresses and\naccount IDs\n\nOnce again, all query parameter values must be URL escaped.',
  request: {
    params: z.object({
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The list of users that are part of a workspace.',
      content: { 'application/json': { schema: PaginatedWorkspaceMembershipsSchema } },
    },
    400: {
      description: 'When more than 90 emails were provided when querying by email.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    401: {
      description: "The request wasn't authenticated.",
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['account'] }, { basic: [] }, { api_key: [] }],
})

