export const putWorkspacesWorkspaceProjectsProjectKeyPermissionsConfigUsersSelectedUserIdRoute =
  createRoute({
    method: 'put',
    path: '/workspaces/{workspace}/projects/{project_key}/permissions-config/users/{selected_user_id}',
    tags: ['Projects'],
    summary: 'Update an explicit user permission for a project',
    description:
      'Updates the explicit user permission for a given user and project. The selected\nuser must be a member of the workspace, and cannot be the workspace owner.\n\nOnly users with admin permission for the project may access this resource.\n\nDue to security concerns, the JWT and OAuth authentication methods are unsupported.\nThis is to ensure integrations and add-ons are not allowed to change permissions.\n\nPermissions can be:\n\n* `admin`\n* `create-repo`\n* `write`\n* `read`',
    request: {
      params: z.object({
        project_key: z
          .string()
          .openapi({
            param: {
              name: 'project_key',
              in: 'path',
              description:
                'The project in question. This is the actual key assigned to the project.\n',
              required: true,
              schema: { type: 'string' },
            },
          }),
        selected_user_id: z
          .string()
          .openapi({
            param: {
              name: 'selected_user_id',
              in: 'path',
              description:
                "This can either be the username, the user's UUID surrounded by curly-braces,\nfor example: {account UUID}, or the user's Atlassian ID.\n",
              required: true,
              schema: { type: 'string' },
            },
          }),
        workspace: z
          .string()
          .openapi({
            param: {
              name: 'workspace',
              in: 'path',
              description:
                'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
              required: true,
              schema: { type: 'string' },
            },
          }),
      }),
      body: BitbucketAppsPermissionsSerializersProjectPermissionUpdateSchemaRequestBody,
    },
    responses: {
      200: {
        description: 'Explicit user permission updated',
        content: {
          'application/json': {
            schema: ProjectUserPermissionSchema,
            examples: {
              response: {
                value: {
                  type: 'project_user_permission',
                  user: {
                    type: 'user',
                    display_name: 'Colin Cameron',
                    uuid: '{d301aafa-d676-4ee0-88be-962be7417567}',
                    account_id: '557058:ba8948b2-49da-43a9-9e8b-e7249b8e324a',
                  },
                  permission: 'write',
                  links: {
                    self: {
                      href: 'https://api.bitbucket.org/2.0/workspaces/atlassian_tutorial/projects/PRJ/permissions-config/users/557058:ba8948b2-49da-43a9-9e8b-e7249b8e324a',
                    },
                  },
                },
              },
            },
          },
        },
      },
      400: {
        description:
          'No permission value was provided or the value is invalid (not one of read, write, create-repo, or admin)',
        content: { 'application/json': { schema: ErrorSchema } },
      },
      401: {
        description: "The user couldn't be authenticated.",
        content: { 'application/json': { schema: ErrorSchema } },
      },
      402: {
        description:
          "You have reached your plan's user limit and must upgrade before giving access to additional users.",
        content: { 'application/json': { schema: ErrorSchema } },
      },
      403: {
        description:
          "The requesting user isn't an admin of the project, or the authentication method was not via app password.",
        content: { 'application/json': { schema: ErrorSchema } },
      },
      404: {
        description:
          "One or more of the workspace, project, and selected user doesn't exist for the given identifiers or the requesting user is not authenticated",
        content: { 'application/json': { schema: ErrorSchema } },
      },
    },
    security: [{ oauth2: ['project:admin'] }, { basic: [] }, { api_key: [] }],
  })

