export const getWorkspacesWorkspacePullrequestsSelectedUserRoute = createRoute({
  method: 'get',
  path: '/workspaces/{workspace}/pullrequests/{selected_user}',
  tags: ['Workspaces', 'Pullrequests'],
  summary: 'List workspace pull requests for a user',
  description:
    'Returns all workspace pull requests authored by the specified user.\n\nBy default only open pull requests are returned. This can be controlled\nusing the `state` query parameter. To retrieve pull requests that are\nin one of multiple states, repeat the `state` parameter for each\nindividual state.\n\nThis endpoint also supports filtering and sorting of the results. See\n[filtering and sorting](/cloud/bitbucket/rest/intro/#filtering) for more details.',
  request: {
    params: z.object({
      selected_user: z
        .string()
        .openapi({
          param: {
            name: 'selected_user',
            in: 'path',
            description:
              "This can either be the username of the pull request author, the author's UUID\nsurrounded by curly-braces, for example: `{account UUID}`, or the author's Atlassian ID.\n",
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      state: z
        .enum(['OPEN', 'MERGED', 'DECLINED', 'SUPERSEDED'])
        .exactOptional()
        .openapi({
          param: {
            name: 'state',
            in: 'query',
            description:
              'Only return pull requests that are in this state. This parameter can be repeated.',
            schema: { type: 'string', enum: ['OPEN', 'MERGED', 'DECLINED', 'SUPERSEDED'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'All pull requests authored by the specified user.',
      content: { 'application/json': { schema: PaginatedPullrequestsSchema } },
    },
    404: {
      description: 'If the specified user does not exist.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['pullrequest'] }, { basic: [] }, { api_key: [] }],
})

export const getWorkspacesWorkspaceSearchCodeRoute = createRoute({
  method: 'get',
  path: '/workspaces/{workspace}/search/code',
  tags: ['Search'],
  summary: 'Search for code in a workspace',
  description:
    'This API will be deprecated on November 1, 2026.\n\nSearch for code in the repositories of the specified workspace.\n\nNote that searches can match in the file\'s text (`content_matches`),\nthe path (`path_matches`), or both.\n\nYou can use the same syntax for the search query as in the UI.\nE.g. to search for "foo" only within the repository "demo",\nuse the query parameter `search_query=foo+repo:demo`.\n\nSimilar to other APIs, you can request more fields using a\n`fields` query parameter. E.g. to get some more information about\nthe repository of matched files, use the query parameter\n`search_query=foo&fields=%2Bvalues.file.commit.repository`\n(the `%2B` is a URL-encoded `+`).\n\nTry `fields=%2Bvalues.*.*.*.*` to get an idea what\'s possible.\n',
  operationId: 'searchWorkspace',
  request: {
    params: z.object({
      workspace: z
        .string()
        .openapi({
          param: {
            name: 'workspace',
            in: 'path',
            description: 'The workspace to search in; either the slug or the UUID in curly braces',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      search_query: z
        .string()
        .openapi({
          param: {
            name: 'search_query',
            in: 'query',
            description: 'The search query',
            required: true,
            schema: { type: 'string' },
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            description: 'Which page of the search results to retrieve',
            required: false,
            schema: { type: 'integer', format: 'int32', default: 1 },
          },
        }),
      pagelen: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'pagelen',
            in: 'query',
            description: 'How many search results to retrieve per page',
            required: false,
            schema: { type: 'integer', format: 'int32', default: 10 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful search',
      content: {
        'application/json': {
          schema: SearchResultPageSchema,
          examples: {
            response: {
              value: {
                size: 1,
                page: 1,
                pagelen: 10,
                query_substituted: false,
                values: [
                  {
                    type: 'code_search_result',
                    content_match_count: 2,
                    content_matches: [
                      {
                        lines: [
                          { line: 2, segments: [] },
                          {
                            line: 3,
                            segments: [
                              { text: 'def ' },
                              { text: 'foo', match: true },
                              { text: '():' },
                            ],
                          },
                          { line: 4, segments: [{ text: '    print("snek")' }] },
                          { line: 5, segments: [] },
                        ],
                      },
                    ],
                    path_matches: [{ text: 'src/' }, { text: 'foo', match: true }, { text: '.py' }],
                    file: {
                      path: 'src/foo.py',
                      type: 'commit_file',
                      links: {
                        self: {
                          href: 'https://api.bitbucket.org/2.0/repositories/my-workspace/demo/src/ad6964b5fe2880dbd9ddcad1c89000f1dbcbc24b/src/foo.py',
                        },
                      },
                    },
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description:
        "If the search request was invalid due to one of the\nfollowing reasons:\n\n* the specified type of target account doesn''t match the actual\naccount type;\n\n* malformed pagination properties;\n\n* missing or malformed search query, in the latter case an error\nkey will be returned in `error.data.key` property.\n",
      content: { 'application/json': { schema: ErrorSchema } },
    },
    404: {
      description:
        'Search is not enabled for the requested workspace, navigate to [https://bitbucket.org/search](https://bitbucket.org/search) to turn it on',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    429: {
      description: 'Too many requests, try again later',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  deprecated: true,
  security: [{ oauth2: ['repository'] }, { basic: [] }, { api_key: [] }],
})

